def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    ERROR_DIV = "#DIV/0!"
    ERROR_CYCLE = "#CYCLE!"

    def tokenize(text):
        pattern = re.compile(
            r"\s+|"
            r"(?:<=|>=|<>|[=<>+\-*/(),:])|"
            r"[A-Za-z][0-9]+|"
            r"[0-9]+"
        )
        tokens = []
        pos = 0
        while pos < len(text):
            match = pattern.match(text, pos)
            if match is None:
                raise ValueError("Invalid formula")
            token = match.group(0)
            pos = match.end()
            if not token.isspace():
                tokens.append(token)
        return tokens

    def parse_formula(text):
        tokens = tokenize(text)
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def take(expected=None):
            nonlocal pos
            token = peek()
            if token is None or (expected is not None and token != expected):
                raise ValueError("Invalid formula")
            pos += 1
            return token

        def parse_expression():
            node = parse_term()
            while peek() in ("+", "-"):
                op = take()
                node = ("bin", op, node, parse_term())
            return node

        def parse_term():
            node = parse_unary()
            while peek() in ("*", "/"):
                op = take()
                node = ("bin", op, node, parse_unary())
            return node

        def parse_unary():
            if peek() == "-":
                take()
                return ("neg", parse_unary())
            return parse_atom()

        def parse_range():
            first = take()
            if not re.fullmatch(r"[A-Z][1-9][0-9]?", first):
                raise ValueError("Invalid range")
            take(":")
            second = take()
            if not re.fullmatch(r"[A-Z][1-9][0-9]?", second):
                raise ValueError("Invalid range")
            return ("range", first, second)

        def parse_argument():
            if (peek() is not None
                    and re.fullmatch(r"[A-Z][1-9][0-9]?", peek())
                    and pos + 1 < len(tokens)
                    and tokens[pos + 1] == ":"):
                return parse_range()
            return ("formula", parse_expression())

        def parse_atom():
            token = peek()
            if token == "(":
                take("(")
                node = parse_expression()
                take(")")
                return node
            if token is not None and token.isdigit():
                take()
                return ("num", int(token))
            if token is not None and re.fullmatch(r"[A-Z][1-9][0-9]?", token):
                take()
                return ("cell", token)
            if token in ("SUM", "MIN", "MAX"):
                name = take()
                take("(")
                args = [parse_argument()]
                while peek() == ",":
                    take(",")
                    args.append(parse_argument())
                take(")")
                return ("func", name, args)
            if token == "IF":
                take("IF")
                take("(")
                left = parse_expression()
                op = take()
                if op not in ("=", "<>", "<", "<=", ">", ">="):
                    raise ValueError("Invalid comparison")
                right = parse_expression()
                take(",")
                then_node = parse_expression()
                take(",")
                else_node = parse_expression()
                take(")")
                return ("if", op, left, right, then_node, else_node)
            raise ValueError("Invalid formula")

        result = parse_expression()
        if pos != len(tokens):
            raise ValueError("Invalid formula")
        return result

    parsed = {}
    for name, content in cells.items():
        if content.startswith("="):
            parsed[name] = parse_formula(content[1:])
        else:
            parsed[name] = int(content)

    cache = {}
    active = set()

    def eval_cell(name):
        if name not in parsed:
            return 0
        if name in cache:
            return cache[name]
        if name in active:
            return ERROR_CYCLE

        active.add(name)
        value = parsed[name] if isinstance(parsed[name], int) else eval_node(parsed[name])
        active.remove(name)
        cache[name] = value
        return value

    def eval_node(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            value = eval_node(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            op, left_node, right_node = node[1], node[2], node[3]
            left = eval_node(left_node)
            if isinstance(left, str):
                return left
            right = eval_node(right_node)
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return ERROR_DIV
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            op, left_node, right_node, then_node, else_node = node[1:]
            left = eval_node(left_node)
            if isinstance(left, str):
                return left
            right = eval_node(right_node)
            if isinstance(right, str):
                return right
            comparisons = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }
            return eval_node(then_node if comparisons[op] else else_node)

        _, name, args = node
        values = []
        for arg in args:
            if arg[0] == "range":
                _, first, second = arg
                c1, r1 = ord(first[0]) - ord("A"), int(first[1:])
                c2, r2 = ord(second[0]) - ord("A"), int(second[1:])
                for row in range(min(r1, r2), max(r1, r2) + 1):
                    for col in range(min(c1, c2), max(c1, c2) + 1):
                        cell_name = chr(ord("A") + col) + str(row)
                        if cell_name in parsed:
                            value = eval_cell(cell_name)
                            if isinstance(value, str):
                                return value
                            values.append(value)
            else:
                value = eval_node(arg[1])
                if isinstance(value, str):
                    return value
                values.append(value)

        if name == "SUM":
            return sum(values)
        if name == "MIN":
            return min(values) if values else 0
        return max(values) if values else 0

    return {name: eval_cell(name) for name in cells}
